files.starter-site/1.0.0/components/starter-he:
{
  "formatVersion": 2,
  "contractVersion": 1,
  "componentKey": "starter-header",
  "label": "Zaglavlje i navigacija",
  "category": "content",
  "renderMode": "static",
  "targets": [
    "web",
    "mobile"
  ],
  "htmlContent": "<header class=\"wfs-header\"><a class=\"wfs-brand\" href=\"{{setting:home-url}}\">{{setting:brand}}</a><nav aria-label=\"Glavna navigacija\">{{each:links}}<a href=\"{{item:url}}\">{{item:label}}</a>{{/each:links}}</nav></header>",
  "styles": [
    {
      "name": "starter-header.css",
      "content": ".wfs-header{max-width:1160px;margin:auto;padding:22px 24px;display:flex;align-items:center;justify-content:space-between;gap:24px;font-family:system-ui,sans-serif}.wfs-brand{font-size:20px;font-weight:800;letter-spacing:-.04em}.wfs-header a{color:inherit;text-decoration:none}.wfs-header nav{display:flex;flex-wrap:wrap;gap:20px;font-size:14px}.wfs-header a:hover{text-decoration:underline}.wfs-header a:focus-visible{outline:2px solid currentColor;outline-offset:5px}@media(max-width:600px){.wfs-header{align-items:flex-start;flex-direction:column;gap:16px}.wfs-header nav{gap:14px}}"
    }
  ],
  "scripts": [],
  "settingsSchema": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "brand",
      "home-url",
      "links"
    ],
    "properties": {
      "brand": {
        "type": "string",
        "maxLength": 100,
        "minLength": 1
      },
      "home-url": {
        "type": "string",
        "maxLength": 2048,
        "minLength": 1,
        "format": "safe-url"
      },
      "links": {
        "type": "array",
        "minItems": 0,
        "maxItems": 8,
        "items": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "label",
            "url"
          ],
          "properties": {
            "label": {
              "type": "string",
              "maxLength": 60,
              "minLength": 1
            },
            "url": {
              "type": "string",
              "maxLength": 2048,
              "minLength": 1,
              "format": "safe-url"
            }
          }
        }
      }
    }
  },
  "providerKey": null,
  "cache": {
    "scope": "public",
    "ttlSeconds": 3600,
    "varyBy": [
      "tenant",
      "locale",
      "release"
    ]
  },
  "access": {
    "visibility": "public",
    "permissions": []
  },
  "seo": {
    "mode": "none"
  }
}

{
  "formatVersion": 2,
  "contractVersion": 1,
  "componentKey": "starter-hero",
  "label": "Naslov i poziv na akciju",
  "category": "content",
  "renderMode": "static",
  "targets": [
    "web",
    "mobile"
  ],
  "htmlContent": "<section class=\"wfs-hero\" data-wf-design-root data-wf-design-surface><div class=\"wfs-wrap\" data-wf-design-content><p class=\"wfs-eyebrow\">{{setting:eyebrow}}</p><h1>{{setting:title}}</h1><p class=\"wfs-lead\">{{setting:lead}}</p><a class=\"wfs-button\" href=\"{{setting:url}}\">{{setting:label}}</a></div></section>",
  "styles": [
    {
      "name": "starter-hero.css",
      "content": ".wfs-hero{padding:88px 24px;background:var(--wf-color-background,#f1f5f3);color:var(--wf-color-text,#172c25)}.wfs-wrap{max-width:1112px;margin:auto}.wfs-eyebrow{font-size:13px;font-weight:750;letter-spacing:.12em;text-transform:uppercase;color:var(--wf-color-primary,#1c6851)}.wfs-hero h1{max-width:850px;margin:20px 0;font-size:clamp(36px,6vw,76px);font-weight:750;line-height:1.05;letter-spacing:-.045em;text-wrap:balance}.wfs-lead{max-width:640px;font-size:19px;line-height:1.7;color:var(--wf-color-muted,#52625d)}.wfs-button{display:inline-flex;margin-top:18px;padding:14px 22px;border-radius:6px;background:var(--wf-color-primary,#1c6851);color:var(--wf-color-on-primary,#fff);text-decoration:none;font-size:15px;font-weight:700}.wfs-button:focus-visible{outline:3px solid currentColor;outline-offset:4px}@media(max-width:600px){.wfs-hero{padding:56px 24px}.wfs-lead{font-size:17px}}"
    }
  ],
  "scripts": [],
  "settingsSchema": {
    "type": "object",
    "additionalProperties": false,
    "required": [
      "eyebrow",
      "title",
      "lead",
      "label",
      "url"
    ],
    "properties": {
      "eyebrow": {
        "type": "string",
        "maxLength": 100
      },
      "title": {
        "type": "string",
        "maxLength": 200,
        "minLength": 1
      },
      "lead": {
        "type": "string",
        "maxLength": 1200
      },
      "label": {
        "type": "string",
        "maxLength": 80,
        "minLength": 1
      },
      "url": {
        "type": "string",
        "maxLength": 2048,
        "minLength": 1,
        "format": "safe-url"
      }
    }
  },
  "providerKey": null,
  "cache": {
    "scope": "public",
    "ttlSeconds": 3600,
    "varyBy": [
      "tenant",
      "locale",
      "release"
    ]
  },
  "access": {
    "visibility": "public",
    "permissions": []
  },
  "seo": {
    "mode": "none"
  },
  "designControls": [
    "padding",
    "textAlign",
    "contentAlign",
    "background",
    "radius"
  ]
}

