");function show(url,alt){main.src=url||\"\";main.alt=alt||\"\";}show(images[0].url,data.name||\"\");gallery.appendChild(main);if(images.length>1){var thumbs=el(\"div\",\"wf-detail__thumbs\");images.forEach(function(image,index){var button=el(\"button\",\"wf-detail__thumb\"),thumb=el(\"img\");button.type=\"button\";if(index===0)button.setAttribute(\"aria-current\",\"true\");thumb.src=image.url||\"\";thumb.alt=\"\";button.appendChild(thumb);button.addEventListener(\"click\",function(){show(image.url,data.name||\"\");thumbs.querySelectorAll(\"button\").forEach(function(other){other.removeAttribute(\"aria-current\");});button.setAttribute(\"aria-current\",\"true\");});thumbs.appendChild(button);});gallery.appendChild(thumbs);}specBody.innerHTML=\"\";var rows=Array.isArray(data.characteristics)?data.characteristics:[];rows.forEach(function(row){var tr=el(\"tr\");tr.appendChild(el(\"th\",\"\",row.name||\"\"));tr.appendChild(el(\"td\",\"\",row.value||\"\"));specBody.appendChild(tr);});specs.hidden=!rows.length;while(relatedGrid.firstChild)relatedGrid.removeChild(relatedGrid.firstChild);var others=Array.isArray(data.related)?data.related:[];others.forEach(function(item){if(!item||!item.id)return;var card=el(\"a\",\"wf-detail__card\");card.href=\"/proizvod?id=\"+encodeURIComponent(item.id);var image=el(\"img\");image.src=item[\"image-url\"]||\"/commonAssets/Images/coming_soon_transparent.png\";image.alt=item.name||\"\";image.loading=\"lazy\";card.appendChild(image);var body=el(\"span\",\"wf-detail__card-body\");if(item.brand)body.appendChild(el(\"span\",\"wf-detail__card-brand\",item.brand));body.appendChild(el(\"strong\",\"\",item.name||item.id));body.appendChild(el(\"span\",\"\",money(item.price,item.currency)));card.appendChild(body);relatedGrid.appendChild(card);});related.hidden=!relatedGrid.children.length;}\nfunction load(){var id=productId();if(!id){showStatus(\"Proizvod nije izabran.\",true);return;}var request=requestId();pendingId=request;status.textContent=\"Uči